public class PaymentTerms {
    private static final Pattern NET_PATTERN = Pattern.compile('^NET\\s*(\\d{1,3})$');
    private static final Pattern DUE_PATTERN = Pattern.compile('^DUE ON RECEIPT$');

    private PaymentTerms() {
    }

    public static Integer parseNetDays(String terms) {
        String originalTerms = terms;
        String trimmed = terms == null ? null : terms.trim();

        if (trimmed == null || trimmed.length() == 0) {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + String.valueOf(originalTerms));
        }

        String upper = trimmed.toUpperCase();

        if (DUE_PATTERN.matcher(upper).matches()) {
            return 0;
        }

        Matcher netMatcher = NET_PATTERN.matcher(upper);
        if (netMatcher.matches()) {
            Integer days = Integer.valueOf(netMatcher.group(1));
            if (days > 180) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }

        throw new UnsupportedTermsException('Unsupported payment terms: ' + String.valueOf(originalTerms));
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
