        // Attach the finalizer before any work so it runs regardless of whether the
        // transaction succeeds or fails.
        System.addFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        // Load the existing accounts, set the Description, and save all-or-nothing.
        // If any record cannot be saved the exception propagates, the transaction
        // rolls back, and none of the changes are kept.
        List<Account> accounts = [SELECT Id FROM Account WHERE Id IN :accountIds];
        for (Account a : accounts) {
            a.Description = 'Synced to ERP';
        }
        update accounts;
    }
}
