        fflib_SObjectSelector selector = Application.Selector.getSelector(Account.SObjectType);
        List<Account> results = new List<Account>();
        for (SObject record : selector.selectByIds(accountIds)) {
            results.add((Account) record);
        }
        return newInstance(results);
    }

