public with sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        // Run every query in user mode so the platform enforces the running user's
        // object, field and sharing access.
        setUserMode();
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        Schema.DescribeSObjectResult describe = Account.SObjectType.getDescribe();

        // Core fields required by the credit team selector
        List<String> fieldNames = new List<String>{
            Account.Id.getName(),
            Account.Name.getName(),
            Account.Industry.getName()
        };

        // Merge in the Credit_Review field set so admins can add fields without
        // any code changes. Fields are deduplicated against the core list.
        Map<String, Schema.FieldSet> fieldSets = describe.fieldSets.getMap();
        Schema.FieldSet creditReview = fieldSets.get('Credit_Review');

        if (creditReview != null) {
            for (String fieldName : creditReview.getFields()) {
                if (!fieldNames.contains(fieldName)) {
                    fieldNames.add(fieldName);
                }
            }
        }

        // Convert field names to SObjectField instances for the fflib query builder
        Map<String, Schema.SObjectField> fieldsMap = describe.fields.getMap();
        List<Schema.SObjectField> result = new List<Schema.SObjectField>();
        for (String fieldName : fieldNames) {
            if (fieldsMap.containsKey(fieldName)) {
                result.add(fieldsMap.get(fieldName));
            }
        }

        return result;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        // Build the account field list from this selector (includes Credit_Review fields)
        List<Schema.SObjectField> accountFields = getSObjectFieldList();
        String accountFieldString = '';
        for (Schema.SObjectField field : accountFields) {
            accountFieldString += (accountFieldString.isEmpty() ? '' : ', ') + field.getName();
        }

        // Build the contact subquery field list from ContactsSelector so it uses
        // that selector's fields and any future changes to it are picked up automatically.
        ContactsSelector contactSelector = new ContactsSelector();
        List<Schema.SObjectField> contactFields = contactSelector.getSObjectFieldList();
        String contactFieldString = '';
        for (Schema.SObjectField field : contactFields) {
            contactFieldString += (contactFieldString.isEmpty() ? '' : ', ') + field.getName();
        }

        String query = 'SELECT ' + accountFieldString +
            ' FROM Account ' +
            ' WHERE Id IN :accountIds ' +
            ' WITH USER_MODE ' +
            ' (SELECT ' + contactFieldString + ' FROM Contacts)';

        return Database.query(query);
    }
}
