public with sharing class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        fflib_SObjectUnitOfWork unitOfWork = new fflib_SObjectUnitOfWork(true);
        List<Account> accountsToCreate = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            if (accountName == null || String.isEmpty(accountName.trim())) {
                continue;
            }

            Account account = new Account(Name = accountName.trim());
            unitOfWork.registerNew(account);
            accountsToCreate.add(account);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null || lastNames.isEmpty()) {
                continue;
            }

            for (String lastName : lastNames) {
                if (lastName == null || String.isEmpty(lastName.trim())) {
                    continue;
                }

                Contact contact = new Contact(LastName = lastName.trim());
                unitOfWork.registerNew(contact);
                unitOfWork.addRelationship(account, contact, 'Account');
            }
        }

        if (accountsToCreate.isEmpty()) {
            return new List<Account>();
        }

        unitOfWork.commitWork();

        Set<String> accountNames = new Set<String>();
        for (Account account : accountsToCreate) {
            accountNames.add(account.Name);
        }

        List<Account> createdAccounts = [
            select Id, Name
            from Account
            where Name in :accountNames
            order by Name
        ];

        return createdAccounts;
    }
}
