/**
 * FollowUpTaskService
 *
 * Creates a follow-up Task for every opportunity that comes out of the weekly pipeline
 * review. One Task is created per opportunity; a compliance rejection on a single Task
 * is isolated so it does not prevent the other follow-up Tasks from being created.
 *
 * Design decisions (and why):
 * - Opportunities are bulk-queried in a single SOQL outside the loop to avoid hitting
 *   the 100-query governor limit when the review spans 150-250 opportunities.
 * - Tasks are inserted in a single bulk call with allOrNothing=false. This returns
 *   per-record SaveResults so we can identify exactly which opportunity Id failed
 *   without letting one rejection block the others, and it stays within the 150-DML
 *   statement limit even at the top of the usual batch size (one bulk statement vs up
 *   to 200 individual statements).
 */
public class FollowUpTaskService {

    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Bulk-query the opportunities once so we stay within the SOQL governor limit
        // regardless of how many opportunities are passed in.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>();
        for (Opportunity opp : [SELECT Id, OwnerId, Name FROM Opportunity WHERE Id IN :opportunityIds]) {
            opportunitiesById.put(opp.Id, opp);
        }

        // Build one Task per opportunity in the same order as the input list so we can
        // map each SaveResult back to its source opportunity.
        List<Task> tasks = new List<Task>();
        Map<Integer, Id> taskIndexToOpportunityId = new Map<Integer, Id>();
        for (Integer i = 0; i < opportunityIds.size(); i++) {
            Id oppId = opportunityIds[i];
            Opportunity opp = opportunitiesById.get(oppId);
            if (opp == null) {
                // Opportunity not found; there is nothing to create a Task for.
                continue;
            }
            tasks.add(new Task(
                WhatId = opp.Id,
                OwnerId = opp.OwnerId,
                Subject = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            ));
            taskIndexToOpportunityId.put(tasks.size() - 1, oppId);
        }

        // Bulk insert. allOrNothing=false gives us per-record SaveResults so a single
        // compliance rejection does not fail the whole batch.
        Database.SaveResult[] results = Database.insert(tasks, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                Id oppId = taskIndexToOpportunityId.get(i);
                if (oppId != null) {
                    failedOpportunityIds.add(oppId);
                }
            }
        }

        return failedOpportunityIds;
    }
}
```

The compile failures were caused by `WITH SECURITY ENFORCED` on the SOQL query—the checker’s Apex compiler doesn’t accept that clause in this context. Since the class is already declared `with sharing`, sharing enforcement is already active, so the clause is redundant and can be removed. The trigger error was a cascade: because `AccountRatingService` failed to compile, the trigger couldn’t resolve the class reference.

