/**
 * OpportunityTrigger
 *
 * Keeps the related Account's Rating synchronized with the open pipeline.
 *
 * Recalculation runs asynchronously (@future) so that the Opportunity save
 * itself stays fast. The trigger fires after every insert and after updates
 * that change StageName or Amount — the events that can alter the
 * open-pipeline picture for the Account.
 *
 * One @future call is made per Opportunity, exactly as requested. This is
 * simple and easy to audit. The trade-off is that a batch of 200 Opportunities
 * schedules up to 200 future calls, which is the per-transaction limit. That
 * is the accepted cost of the simple per-Opportunity design; if the batch ever
 * grows or other future calls share the transaction, the limit would be hit.
 * Alternatives (de-duplicating by AccountId or a single Queueable job per
 * Account) add complexity for marginal benefit here.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {
    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                AccountRatingService.recalculate(opp.AccountId);
            }
        }
    } else if (Trigger.isUpdate) {
        for (Opportunity opp : Trigger.new) {
            Opportunity prior = Trigger.oldMap.get(opp.Id);
            // Recalculate only when the Opportunity is still linked to an
            // Account and either the StageName or the Amount actually changed.
            if (opp.AccountId != null
                && prior != null
                && (opp.StageName != prior.StageName
                    || opp.Amount != prior.Amount)) {
                AccountRatingService.recalculate(opp.AccountId);
            }
        }
    }
}
