/**
 * AccountRatingService
 *
 * Asynchronously recomputes the Rating of an Account from its open
 * Opportunities:
 *
 *   Hot   - at least one open Opportunity with Amount >= 100,000
 *   Warm  - open Opportunities exist, but none reach 100,000
 *   Cold  - no open Opportunities
 *
 * The method is @future so it runs in its own transaction after the
 * Opportunity save commits, keeping the save fast.
 */
public with sharing class AccountRatingService {

    private static final Decimal BIG_OPPORTUNITY_AMOUNT = 100000;

    @future
    public static void recalculate(Id accountId) {
        Integer openCount = 0;
        Integer largeOpenCount = 0;

        for (Opportunity opp : [
                SELECT Id, Amount, IsClosed
                FROM   Opportunity
                WHERE  AccountId = :accountId
                       AND IsClosed = false
        ]) {
            openCount++;
            if (opp.Amount != null && opp.Amount >= BIG_OPPORTUNITY_AMOUNT) {
                largeOpenCount++;
            }
        }

        String rating;
        if (openCount == 0) {
            rating = 'Cold';
        } else if (largeOpenCount > 0) {
            rating = 'Hot';
        } else {
            rating = 'Warm';
        }

        // Persist the result. The Account should still exist; guard against
        // the rare race where it was deleted after the future call was queued.
        Account acct = new Account(Id = accountId, Rating = rating);
        try {
            update acct;
        } catch (DmlException e) {
            // Account no longer exists or is not updatable; the rating will
            // be corrected on the next Opportunity change.
        }
    }
}
