public with sharing class LineItemDiscountHandler {
    /**
     * Cache of productId -> standard discount resolved within this transaction.
     * Keeps the pricing rule in PricingRules while avoiding repeated SOQL for
     * the same product across many line items (e.g. a 200-line CPQ quote).
     */
    private static Map<Id, Decimal> discountByProduct = new Map<Id, Decimal>();

    /**
     * Sets the standard product discount on new lines that have no explicit
     * Discount. Lines that already have a Discount (including 0) keep it.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lineItems) {
        for (OpportunityLineItem line : lineItems) {
            if (line.Discount == null) {
                Decimal discount = discountByProduct.get(line.Product2Id);
                if (discount == null) {
                    discount = PricingRules.standardDiscountFor(line.Product2Id);
                    discountByProduct.put(line.Product2Id, discount);
                }
                line.Discount = discount;
            }
        }
    }
}
