// NOTE: The brief requests an org-wide contact map ([SELECT Id, AccountId, MailingCountry FROM Contact]).
// On an org with ~2.3M contacts that is not viable: it exceeds the 50,000-row SOQL limit and the heap limit.
// The bulk-safe equivalent is one selective query for contacts belonging to the accounts whose
// BillingCountry actually changed. No queries run in loops, and DML is chunked at 200.
public with sharing class AccountCountrySync {

    public static void onBillingCountryChanged(Map<Id, Account> newAccounts, Map<Id, Account> oldAccounts) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccounts == null) {
            return;
        }

        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> oldBillingCountryByAccount = new Map<Id, String>();
        Map<Id, String> newBillingCountryByAccount = new Map<Id, String>();

        // Identify accounts whose BillingCountry changed.
        for (Account acc : newAccounts.values()) {
            Account oldAcc = oldAccounts.get(acc.Id);
            if (oldAcc == null) {
                continue;
            }

            String newCountry = acc.BillingCountry;
            String oldCountry = oldAcc.BillingCountry;

            Boolean changed = false;
            if ((newCountry == null) != (oldCountry == null)) {
                // One side became blank / the other became populated.
                changed = true;
            } else if (newCountry != null && !newCountry.equals(oldCountry)) {
                // Both populated but different values.
                changed = true;
            }

            if (changed) {
                changedAccountIds.add(acc.Id);
                oldBillingCountryByAccount.put(acc.Id, oldCountry);
                newBillingCountryByAccount.put(acc.Id, newCountry);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        // One query: load only the contacts of the changed accounts.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            String oldCountry = oldBillingCountryByAccount.get(c.AccountId);

            // Follow the HQ move only when the contact has no mailing country or its mailing country
            // matches the account's previous billing country. Contacts with another mailing country
            // work abroad and are left alone.
            if (String.isBlank(c.MailingCountry) || c.MailingCountry.equals(oldCountry)) {
                Contact updated = new Contact(Id = c.Id);
                updated.MailingCountry = newBillingCountryByAccount.get(c.AccountId);
                contactsToUpdate.add(updated);
            }
        }

        if (contactsToUpdate.isEmpty()) {
            return;
        }

        // Update in chunks of 200 and allow partial success so one failing contact
        // does not roll back the whole batch.
        for (Integer i = 0; i < contactsToUpdate.size(); i += 200) {
            Integer chunkEnd = Math.min(i + 200, contactsToUpdate.size());
            List<Contact> chunk = new List<Contact>();
            for (Integer j = i; j < chunkEnd; j++) {
                chunk.add(contactsToUpdate[j]);
            }
            Database.update(chunk, false);
        }
    }
}
