    handleReset() {
        this.editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = [...this.editors];
        let allValid = true;

        // Validate every editor so that all invalid lines show their errors at once.
        editors.forEach((editor) => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (allValid) {
            this.errorMessage = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines }
            }));
        } else {
            this.errorMessage = true;
        }
    }
}
