public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        // Null or empty input returns an empty list.
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        Integer size = gifts.size();

        // Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> imports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c record = new npsp__DataImport__c();
            record.npsp__Contact1_Firstname__c = gift.firstName;
            record.npsp__Contact1_Lastname__c = gift.lastName;
            record.npsp__Contact1_Personal_Email__c = gift.email;
            record.npsp__Donation_Amount__c = gift.amount;
            record.npsp__Donation_Date__c = gift.giftDate;
            // npsp__Donation_Donor__c is resolved by NPSP during processing
            // once the contact has been matched or created.
            imports.add(record);
        }

        // Bulk insert all staging records in a single DML operation.
        // NPSP's Data Import trigger processes them synchronously in the
        // same transaction, applying the org's Data Import settings
        // (npsp__Data_Import_Settings__c) for contact matching
        // (first name, last name, email) and donation processing rules.
        insert imports;

        // Map each staged record Id back to its original input position
        // so results can be reassembled in input order.
        Map<Id, Integer> importIdToInputIndex = new Map<Id, Integer>();
        for (Integer i = 0; i < imports.size(); i++) {
            importIdToInputIndex.put(imports[i].Id, i);
        }

        // Retrieve NPSP's results for our staged records. Each row's
        // npsp__Status__c indicates whether NPSP imported the row.
        Map<Integer, npsp__DataImport__c> inputIndexToImport = new Map<Integer, npsp__DataImport__c>();
        for (npsp__DataImport__c record : [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :importIdToInputIndex.keySet()
        ]) {
            inputIndexToImport.put(importIdToInputIndex.get(record.Id), record);
        }

        // Build one ImportResult per gift, in original input order.
        // Rows NPSP rejects do not stop the others; their result carries
        // NPSP's failure message.
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < size; i++) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c record = inputIndexToImport.get(i);

            if (record != null && 'Imported' == record.npsp__Status__c) {
                result.success = true;
                result.contactId = record.npsp__Contact1Imported__c;
                result.opportunityId = record.npsp__DonationImported__c;
            } else {
                result.success = false;
                result.errorMessage = (record != null && record.npsp__FailureInformation__c != null)
                    ? record.npsp__FailureInformation__c
                    : 'NPSP did not import this row and no failure information was recorded.';
            }
            results.add(result);
        }

        return results;
    }
}
