public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Null or empty input does nothing.
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---- Validation: no DML is performed until every check passes ----
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> seenPairs = new Set<String>();

        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('opportunityId and contactId are required on every request.');
            }
            String pair = req.opportunityId + '|' + req.contactId;
            if (seenPairs.contains(pair)) {
                throw new SoftCreditException('Duplicate opportunity/contact pair within the same call: ' + pair);
            }
            seenPairs.add(pair);
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Load the opportunities once for the primary contact and the opportunity amount.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>();
        for (Opportunity opp : [
            SELECT Id, npsp__Primary_Contact__c, npsp__Amount__c, Amount
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]) {
            opportunitiesById.put(opp.Id, opp);
        }

        for (SoftCreditRequest req : requests) {
            Opportunity opp = opportunitiesById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId.equals(opp.npsp__Primary_Contact__c)) {
                throw new SoftCreditException('The contact is the primary contact of the opportunity.');
            }
            if (req.amount == null) {
                throw new SoftCreditException('Amount is required.');
            }
            if (req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive.');
            }
            Decimal opportunityAmount = opp.npsp__Amount__c != null ? opp.npsp__Amount__c : opp.Amount;
            if (opportunityAmount != null && req.amount > opportunityAmount) {
                throw new SoftCreditException('Amount cannot exceed the opportunity amount.');
            }
        }

        // ---- Load existing related data (SOQL only, bulk-safe) ----
        // contactId -> opportunityId -> list of existing contact roles
        Map<Id, Map<Id, List<OpportunityContactRole>>> ocrsByContactOpp = new Map<Id, Map<Id, List<OpportunityContactRole>>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, OpportunityId, Role
            FROM OpportunityContactRole
            WHERE ContactId IN :contactIds
              AND OpportunityId IN :opportunityIds
        ]) {
            Map<Id, List<OpportunityContactRole>> byOpp = ocrsByContactOpp.get(ocr.ContactId);
            if (byOpp == null) {
                byOpp = new Map<Id, List<OpportunityContactRole>>();
                ocrsByContactOpp.put(ocr.ContactId, byOpp);
            }
            List<OpportunityContactRole> list = byOpp.get(ocr.OpportunityId);
            if (list == null) {
                list = new List<OpportunityContactRole>();
                byOpp.put(ocr.OpportunityId, list);
            }
            list.add(ocr);
        }

        // contactId -> opportunityId -> existing partial soft credit (first match)
        Map<Id, Map<Id, npsp__Partial_Soft_Credit__c>> softCreditsByContactOpp = new Map<Id, Map<Id, npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c sc : [
            SELECT Id, npsp__Contact__c, npsp__Opportunity__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c, npsp__Contact_Name__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Contact__c IN :contactIds
              AND npsp__Opportunity__c IN :opportunityIds
        ]) {
            Map<Id, npsp__Partial_Soft_Credit__c> byOpp = softCreditsByContactOpp.get(sc.npsp__Contact__c);
            if (byOpp == null) {
                byOpp = new Map<Id, npsp__Partial_Soft_Credit__c>();
                softCreditsByContactOpp.put(sc.npsp__Contact__c, byOpp);
            }
            if (!byOpp.containsKey(sc.npsp__Opportunity__c)) {
                byOpp.put(sc.npsp__Opportunity__c, sc);
            }
        }

        Map<Id, String> contactNames = new Map<Id, String>();
        for (Contact c : [SELECT Id, Name FROM Contact WHERE Id IN :contactIds]) {
            contactNames.put(c.Id, c.Name);
        }

        // ---- Ensure exactly one OpportunityContactRole per (contact, opportunity)
        //      with Role equal to the requested role ----
        Map<String, Id> ocrIdByRequestKey = new Map<String, Id>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.contactId + '|' + req.opportunityId;
            List<OpportunityContactRole> existingOCRs = ocrsByContactOpp.get(req.contactId) != null ?
                ocrsByContactOpp.get(req.contactId).get(req.opportunityId) : new List<OpportunityContactRole>();

            Id ocrId;
            if (existingOCRs.isEmpty()) {
                OpportunityContactRole ocr = new OpportunityContactRole();
                ocr.ContactId = req.contactId;
                ocr.OpportunityId = req.opportunityId;
                ocr.Role = req.role;
                ocrsToInsert.add(ocr);
            } else {
                ocrId = existingOCRs[0].Id;
                if (!existingOCRs[0].Role.equals(req.role)) {
                    existingOCRs[0].Role = req.role;
                    ocrsToUpdate.add(existingOCRs[0]);
                }
            }
            ocrIdByRequestKey.put(key, ocrId);
        }

        // DML: contact roles (at most 2 statements)
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }
        if (!ocrsToInsert.isEmpty()) {
            List<OpportunityContactRole> insertedOCRs = insert ocrsToInsert;
            for (OpportunityContactRole inserted : insertedOCRs) {
                String key = inserted.ContactId + '|' + inserted.OpportunityId;
                ocrIdByRequestKey.put(key, inserted.Id);
            }
        }

        // ---- Ensure exactly one partial soft credit per (contact, opportunity) ----
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpdate = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> softCreditsToInsert = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.contactId + '|' + req.opportunityId;
            Id ocrId = ocrIdByRequestKey.get(key);

            Map<Id, npsp__Partial_Soft_Credit__c> byOpp = softCreditsByContactOpp.get(req.contactId);
            npsp__Partial_Soft_Credit__c existingSC = byOpp != null ? byOpp.get(req.opportunityId) : null;

            if (existingSC == null) {
                npsp__Partial_Soft_Credit__c sc = new npsp__Partial_Soft_Credit__c();
                sc.npsp__Opportunity__c = req.opportunityId;
                sc.npsp__Contact__c = req.contactId;
                sc.npsp__Amount__c = req.amount;
                sc.npsp__Role_Name__c = req.role;
                sc.npsp__Contact_Role_ID__c = ocrId;
                sc.npsp__Contact_Name__c = contactNames.get(req.contactId);
                softCreditsToInsert.add(sc);
            } else {
                Boolean changed = false;
                if (existingSC.npsp__Amount__c != req.amount) {
                    existingSC.npsp__Amount__c = req.amount;
                    changed = true;
                }
                if (!existingSC.npsp__Role_Name__c.equals(req.role)) {
                    existingSC.npsp__Role_Name__c = req.role;
                    changed = true;
                }
                if (!existingSC.npsp__Contact_Role_ID__c.equals(ocrId)) {
                    existingSC.npsp__Contact_Role_ID__c = ocrId;
                    changed = true;
                }
                String name = contactNames.get(req.contactId);
                if (!existingSC.npsp__Contact_Name__c.equals(name)) {
                    existingSC.npsp__Contact_Name__c = name;
                    changed = true;
                }
                if (changed) {
                    softCreditsToUpdate.add(existingSC);
                }
            }
        }

        // DML: partial soft credits (at most 2 statements)
        if (!softCreditsToUpdate.isEmpty()) {
            update softCreditsToUpdate;
        }
        if (!softCreditsToInsert.isEmpty()) {
            insert softCreditsToInsert;
        }
    }
