/**
 * GiftService records donations (gifts) that have already been received,
 * following the Nonprofit Success Pack (NPSP) Household Account model.
 */
public with sharing class GiftService {

    /**
     * Records a Closed Won donation of `amount` from the contact, closed on
     * `giftDate`. The gift is credited to the contact's household account, the
     * contact is the primary contact (Donor role), every other household
     * member receives a Household Member role, and exactly one paid payment is
     * created for the full amount on the gift date.
     *
     * @param contactId The Contact who made the gift.
     * @param amount    The gift amount; must be greater than zero.
     * @param giftDate  The date the gift was received (also the close date).
     * @return The Id of the created Opportunity.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required.');
        }

        // The contact must exist.
        Contact contact = [
            SELECT FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contact == null) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }

        // In the Household Account model, the household is tracked as an Account
        // and the contact's AccountId points to that household account.
        Id householdAccountId = contact.AccountId;
        if (householdAccountId == null) {
            throw new IllegalArgumentException('Contact is not a member of a household.');
        }

        // Every member of the household (contacts sharing the same household account).
        Set<Id> householdMemberIds = new Set<Id>();
        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdAccountId
        ]) {
            householdMemberIds.add(member.Id);
        }

        // Create the opportunity, credited to the household account.
        String dateString = formatDate(giftDate);
        String firstName = contact.FirstName == null ? '' : contact.FirstName;
        String lastName = contact.LastName == null ? '' : contact.LastName;
        Opportunity opp = new Opportunity(
            Name = (firstName + ' ' + lastName + ' Donation ' + dateString).trim(),
            StageName = 'Closed Won',
            CloseDate = giftDate,
            Amount = amount,
            AccountId = householdAccountId,
            npsp__Primary_Contact__c = contactId
        );
        insert opp;

        // Contact roles: the donor is the primary contact (Donor role); every
        // other household member is a Household Member. Each contact receives
        // at most one role, so no contact ends up with more than one role.
        List<OpportunityContactRole> roles = new List<OpportunityContactRole>();
        roles.add(new OpportunityContactRole(
            OpportunityId = opp.Id,
            ContactId = contactId,
            Role = 'Donor',
            IsPrimary = true
        ));
        for (Id memberId : householdMemberIds) {
            if (memberId == contactId) {
                continue;
            }
            roles.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = memberId,
                Role = 'Household Member'
            ));
        }
        insert roles;

        // Exactly one payment: paid in full on the gift date.
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        return opp.Id;
    }

    /**
     * Formats a Date as yyyy-MM-dd using the date's own fields (timezone safe).
     */
    private static String formatDate(Date d) {
        return String.valueOf(d.year()) + '-' +
               String.leftPad(String.valueOf(d.month()), 2, '0') + '-' +
               String.leftPad(String.valueOf(d.day()), 2, '0');
    }
}
