/**
 * OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management (TDTM) handler for Opportunity.
 *
 * Register this class on the Opportunity object with:
 *   Class           : OPP_MajorGiftFollowUp_TDTM
 *   Object          : Opportunity
 *   Trigger Action  : AfterInsert;AfterUpdate
 *   Load Order      : 5
 *   Asynchronous    : false
 *
 * Behaviour: the first time an Opportunity becomes a major gift
 * (StageName = 'Closed Won' and Amount >= 5,000) a single follow-up Task is
 * created. An Opportunity that already qualified is never given a second task,
 * so edits to an existing major gift do not create duplicate tasks.
 *
 * Bulk-safe: one Task list is built from the trigger context and inserted with
 * a single DML statement. No SOQL is issued.
 */
global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;
    private static final Integer FOLLOW_UP_DAYS = 3;

    global override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist,
                                                      List<SObject> oldlist,
                                                      npsp.TDTM_Runnable.Action triggerAction,
                                                      Schema.DescribeSObjectResult objResult) {

        // This handler is only registered for AfterInsert and AfterUpdate.
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        // Remember which records already qualified before this operation so we
        // do not create a duplicate task for an already-qualified gift.
        // For AfterInsert, oldlist is empty, so nothing is pre-qualified.
        Set<Id> previouslyQualifiedIds = new Set<Id>();
        if (oldlist != null) {
            for (SObject oldObj : oldlist) {
                if (isMajorGift(oldObj)) {
                    previouslyQualifiedIds.add(oldObj.Id);
                }
            }
        }

        // Build follow-up tasks for records that are newly qualified.
        List<Task> tasksToInsert = new List<Task>();
        for (SObject newObj : newlist) {
            Opportunity opp = (Opportunity) newObj;
            if (opp == null) {
                continue;
            }

            boolean nowQualified = isMajorGift(opp);
            boolean wasQualified = previouslyQualifiedIds.contains(opp.Id);

            // Create a task only when the Opportunity transitions into the
            // major-gift state. Edits to an already-qualified gift are skipped.
            if (nowQualified && !wasQualified) {
                Task t = new Task();
                t.Subject = 'Major gift thank-you call';
                t.Priority = 'High';
                t.Status = 'Not Started';
                t.WhatId = opp.Id;
                t.WhoId = opp.npsp__Primary_Contact__c; // may be null
                t.OwnerId = opp.OwnerId;
                if (opp.CloseDate != null) {
                    t.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_DAYS);
                }
                tasksToInsert.add(t);
            }
        }

        // Single DML statement, no SOQL.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return new npsp.TDTM_Runnable.DmlWrapper();
    }

    private boolean isMajorGift(SObject obj) {
        if (obj == null) {
            return false;
        }
        Opportunity opp = (Opportunity) obj;
        if (opp.StageName == null || opp.Amount == null) {
            return false;
        }
        return opp.StageName.equals('Closed Won') && opp.Amount >= MAJOR_GIFT_AMOUNT;
    }
}
