public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // If the running user cannot read the object at all, return an empty list
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Determine which of the three custom fields the running user can read
        Map<String, Boolean> fieldAccessible = new Map<String, Boolean>{
            'Department__c' => Schema.FB_Employee__c.Department__c.isAccessible(),
            'Salary__c' => Schema.FB_Employee__c.Salary__c.isAccessible(),
            'Personal_Email__c' => Schema.FB_Employee__c.Personal_Email__c.isAccessible()
        };

        // Build a dynamic SOQL query that includes only the fields the user can read.
        // Id and Name are standard fields and are always readable when the object is accessible.
        String query = 'SELECT Id, Name';
        if (fieldAccessible.get('Department__c')) {
            query += ', Department__c';
        }
        if (fieldAccessible.get('Salary__c')) {
            query += ', Salary__c';
        }
        if (fieldAccessible.get('Personal_Email__c')) {
            query += ', Personal_Email__c';
        }
        query += ' FROM FB_Employee__c ORDER BY Name ASC';

        // Execute the query. Sharing is enforced by the with sharing declaration.
        return (List<FB_Employee__c>) Database.query(query);
    }
}
