/*
 * Trigger Action: TA_Account_CreateOnboardingTask
 *
 * After Insert on Account. Creates an onboarding Task for each new Account whose Type is
 * 'Customer - Direct' or 'Customer - Channel'.
 *
 * Bulk-safe design:
 *   - All qualifying Tasks are built in memory and inserted with a single DML statement.
 *   - No DML is executed at all when no Account qualifies (empty list check).
 *
 * Note: this action implements the TriggerAction interface directly (the installed
 * MetadataTriggerHandler is not virtual and its methods are not overridable), so the
 * framework instantiates the class by name and invokes the matching interface method.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        // This action is registered for Account After Insert only; guard defensively.
        if (!(triggerNew[0] instanceof Account)) {
            return;
        }

        List<Task> tasks = new List<Task>();
        Date activityDate = Date.today().addDays(7);

        for (SObject record : triggerNew) {
            Account acct = (Account) record;
            String acctType = acct.Type;

            if (acctType == 'Customer - Direct' || acctType == 'Customer - Channel') {
                tasks.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = acct.Id,
                    OwnerId = acct.OwnerId,
                    ActivityDate = activityDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        // Single DML statement only when there is work to do; no DML otherwise.
        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
